code_sketch:
double prev = now_seconds();          /* clock_gettime(CLOCK_MONOTONIC) */
const double dt = 1.0 / 60.0;
double lag = 0.0;
for (;;) {
    double cur = now_seconds();
    lag += cur - prev; prev = cur;
    if (lag > 0.25) lag = 0.25;       /* clamp: no spiral of death */
    drain_input();
    while (lag >= dt) { step(dt); lag -= dt; }
    render(lag / dt);                 /* interpolate previous -> current */
    nanosleep_ms(dt * 1000.0 * 0.5);  /* coarse; the loop re-reads the clock */
}

