#define SDL_MAIN_USE_CALLBACKS
#include <SDL3/SDL_main.h>
SDL_AppResult SDL_AppInit(void **state, int argc, char **argv) {
    *state = world_new();
    return SDL_APP_CONTINUE;                 /* one-time setup only */
}
SDL_AppResult SDL_AppEvent(void *state, SDL_Event *e) {
    return e->type == SDL_EVENT_QUIT ? SDL_APP_SUCCESS : SDL_APP_CONTINUE;
}
SDL_AppResult SDL_AppIterate(void *state) {  /* SDL calls this at SDL's cadence */
    step(dt_from_clock());                   /* never sleep or loop here */
    render();
    return SDL_APP_CONTINUE;
}
